const serviceChoices = [
 {id:'baseball',name:'Baseball lanes',heading:'A lane for your next practice.',description:'Rent an indoor batting lane for individual work or a small group. Baseball pitching machine lanes are available, and the air-conditioned space gives you a comfortable place to practice throughout the year.',details:['Standard lane rental: $40 per hour','Additional players: $10 each; four players maximum','Reserve available times through our online scheduler'],image:'facility',action:'Explore baseball lanes',url:'#baseball'},
 {id:'softball',name:'Softball lanes',heading:'Make time for your softball game.',description:'Bring your hitting routine indoors. Our softball pitching machine lanes welcome individual players and small groups, whether you are getting ready for the season or making practice part of your week.',details:['Softball pitching machine lane options','Standard lane rental: $40 per hour','Up to four players per lane, with additional-player fees'],image:'training',action:'Explore softball lanes',url:'#softball'},
 {id:'lessons',name:'Private lessons',heading:'Work on the skills that matter to you.',description:'Get personal attention from an experienced coach. One-on-one instruction gives baseball and softball players space to work on their individual skills, refine their technique, and ask questions along the way.',details:['Personalized baseball and softball instruction','Support for individual skill development','Contact our team to discuss coaching availability and rates'],image:'facility',action:'Learn about private lessons',url:'#lessons'},
 {id:'hittrax',name:'HitTrax',heading:'Bring feedback into your batting practice.',description:'HitTrax adds real-time data and analytics to your session. Use that feedback to understand your swing mechanics and make more informed adjustments as you practice.',details:['Real-time data during batting practice','Feedback to support swing development','Ask our team about session length and current rates'],image:'training',action:'Discover HitTrax',url:'#hittrax'},
 {id:'teams',name:'Teams & groups',heading:'Bring your team. Give everyone room.',description:'Reserve space for a group session or ask about the whole facility. Elite welcomes individuals, groups, and teams, with room for batting practice and drills. Our staff can help you choose the right arrangement for your group.',details:['Single-lane and whole-facility rental options','Up to six cages for facility bookings','Contact us to coordinate group size, timing, and pricing'],image:'facility',action:'Ask about a team session',url:'mailto:info@eliteperformancecenterca.com'}
];
function setupServices(){
 const cards=document.querySelector('main > .section .cards');
 if(!document.querySelector('.hero')||!cards)return;
 const section=cards.closest('.section');section.classList.add('service-section');
 section.innerHTML=`<div class="service-heading"><h2>Find the right way to train.</h2><p>From a lane for an hour to a session with the whole team, choose the space and support that fit your practice.</p></div><div class="service-explorer"><div class="service-choices" role="group" aria-label="Choose a training service">${serviceChoices.map((s,i)=>`<button type="button" data-service="${i}" aria-pressed="${i===0}" aria-controls="service-detail">${s.name}<span aria-hidden="true">+</span></button>`).join('')}</div><div class="service-detail" id="service-detail"><div class="service-photo">${image('facility')}<p>Inside our Clovis facility</p></div><div class="service-copy"></div></div></div>`;
 const buttons=section.querySelectorAll('[data-service]');let active=-1;
 function choose(index){if(active===index)return;active=index;const s=serviceChoices[index];buttons.forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===index));b.querySelector('span').textContent=i===index?'−':'+';});const photo=section.querySelector('.service-photo img');photo.src=`assets/${s.image}.jpg`;photo.alt='Inside Elite Performance Center in Clovis';section.querySelector('.service-copy').innerHTML=`<h3>${s.heading}</h3><p>${s.description}</p><ul>${s.details.map(x=>`<li>${x}</li>`).join('')}</ul><a class="button" href="${s.url}">${s.action}</a>`;}
 buttons.forEach((b,i)=>{b.onclick=()=>choose(i);b.onpointerenter=e=>{if(e.pointerType==='mouse')choose(i)};b.onfocus=()=>choose(i);b.onkeydown=e=>{if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'||e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].focus();}};});choose(0);
 // HitTrax is now part of the service explorer, avoiding another repeated image.
 document.querySelector('main > .feature')?.remove();
 const community=document.querySelector('.community');if(community){community.innerHTML='<div><h2>A local place to learn the game.</h2><p>Elite Performance Center serves baseball and softball players from Fresno and Clovis. The facility was created to give young athletes access to training resources, experienced instruction, and a supportive place to practice.</p><p>You do not have to belong to a team to train here. Individual players, families, and groups are welcome. Book a lane, ask about lessons, or talk to our staff about making space for your team.</p><a class="textlink" href="#contact">Plan your visit</a></div><aside><h3>Before your first visit</h3><details><summary>How do I reserve a lane?</summary><p>Use the online scheduler to see availability and reserve your session. Contact the facility directly for lessons or group arrangements.</p></details><details><summary>Can I train with friends?</summary><p>Yes. Standard lane rentals allow up to four players, with a fee for each additional player. For larger groups, ask our staff about facility rentals.</p></details><details><summary>Where is the facility?</summary><p>906 Barstow Avenue, Suite A, Clovis, CA 93612. <a href="#contact">See opening hours and directions.</a></p></details></aside>';}
}
setupServices();window.addEventListener('hashchange',setupServices);
